-- Reihe 1 · Bauform EIN-1 (term_einsetzen), erzeugt von tools/bauform.sh (scripts/bauformen/bauformen/ein_1.py).
-- Steckbrief und 71 gruene Instanzen (Status draft, Pool session). Pruefmaschine: 71 gruen,
-- 1 rot (verworfen). Blindloeser: {"geloest": 10, "abweichend": [], "bestanden": true}.
-- Vorschau: docs/reihe1/A/bauformen/EIN-1.json. Aendert sich der Steckbrief, steigt die Version (Trigger); die
-- Instanzen tragen die neue Version, die alten bleiben fuer die Historie. Der Steckbrief enthaelt den Hash des
-- Generators: aendert sich der Generator, steigt die Version ebenfalls.
--
-- Pruefabfrage: select count(*) from tasks t join bauformen b on b.id = t.bauform_id
--                where b.schluessel = 'EIN-1' and t.bauform_version = b.version;   → 71
do $$ begin perform set_config('edvance.bauform_export', '1', true); end $$;
insert into public.bauformen (schluessel, skill_key, kernidee_key, format, rollen, steckbrief, generator_pfad, status,
                              pruefprotokoll, blindloeser, verdacht)
values ('EIN-1', 'term_einsetzen', null, 'zahl', '{warmup,uebung,home}'::text[],
        '{"text": "Berechne f({x0}) für f(x) = {term}.", "stufen": {"1": "f(x) = x² + b·x + c, x von 1 bis 6 (ohne 2)", "2": "a = 1, x von −1 bis −6 (ohne −2)", "3": "a ∈ {−3, −2, 2, 3}, x von −1 bis −5 (ohne −2)"}, "fehlbilder": [{"key": "qf_quadrat_als_verdopplung", "regel": "x² als 2·x gerechnet", "gilt_fuer_stufen": [1, 2, 3], "rueckmeldung": "x² heißt x mal x, nicht 2 mal x."}, {"key": "qf_einsetzen_vorzeichen", "regel": "−x² statt (−x)²", "gilt_fuer_stufen": [2, 3], "rueckmeldung": "Setz negative Zahlen in Klammern ein: (−3)² = 9."}, {"key": "qf_ax_quadriert", "regel": "(a·x)² statt a·x²", "gilt_fuer_stufen": [3], "rueckmeldung": "Nur x wird quadriert, die Zahl davor nicht. Erst quadrieren, dann malnehmen."}], "hinweise": ["Ersetze jedes x durch {xk}.", "Rechne zuerst das Quadrat, dann die Produkte, dann die Summe.", "Schreib es auf: f({x0}) = {eingesetzt}."], "loesungsweg": ["f({x0}) = {eingesetzt}", "= {zwischen}", "= {ergebnis}"], "warum": null, "kontext": null, "figur": null, "zeit_sek": 60, "kann_entfallen": false, "generator_hash": "f52d1b0457d3"}'::jsonb, 'scripts/bauformen/bauformen/ein_1.py', 'zur_pruefung',
