: "Berechne f(−3) für f(x) = 2x² − x − 4.", "payload": {"kind": "short_input", "prompt": "Berechne f(−3) für f(x) = 2x² − x − 4."}, "params": {"a": 2, "b": -1, "c": -4, "x": -3}, "stufe": 3, "rolle": "warmup", "pm": {"1": {"ok": true}, "2": {"ok": true}, "3": {"ok": true}, "4": {"ok": true}, "5": {"ok": true}, "6": {"ok": true}, "7": {"ok": true}}, "afb": "II", "correct": ["17", "+17"], "acceptance": {"canonical": "17", "equivalents": ["+17"], "known_errors": {"-13": "qf_quadrat_als_verdopplung", "−13": "qf_quadrat_als_verdopplung", "-19": "qf_einsetzen_vorzeichen", "−19": "qf_einsetzen_vorzeichen", "35": "qf_ax_quadriert"}}, "parts": null, "figur": null, "optionen": null, "solution": "f(−3) = 2 · (−3)² + (−1) · (−3) + (−4)\n= 18 + 3 + (−4)\n= 17", "hints": [{"level": 1, "text": "Ersetze jedes x durch (−3).", "status": "entwurf"}, {"level": 2, "text": "Rechne zuerst das Quadrat, dann die Produkte, dann die Summe.", "status": "entwurf"}, {"level": 3, "text": "Schreib es auf: f(−3) = 2 · (−3)² + (−1) · (−3) + (−4).", "status": "entwurf"}]}, {"suffix": "uebung-s3-2067aabd40", "input_type": "NUMERIC", "frage": "Berechne f(−3) für f(x) = −2x² − 4x.", "payload": {"kind": "short_input", "prompt": "Berechne f(−3) für f(x) = −2x² − 4x."}, "params": {"a": -2, "b": -4, "c": 0, "x": -3}, "stufe": 3, "rolle": "uebung", "pm": {"1": {"ok": true}, "2": {"ok": true}, "3": {"ok": true}, "4": {"ok": true}, "5": {"ok": true}, "6": {"ok": true}, "7": {"ok": true}}, "afb": "II", "correct": ["-6", "−6"], "acceptance": {"canonical": "-6", "equivalents": ["−6"], "known_errors": {"24": "qf_quadrat_als_verdopplung", "30": "qf_einsetzen_vorzeichen", "48": "qf_ax_quadriert"}}, "parts": null, "figur": null, "optionen": null, "solution": "f(−3) = −2 · (−3)² + (−4) · (−3)\n= (−18) + 12\n= −6", "hints": [{"level": 1, "text": "Ersetze jedes x durch (−3).", "status": "entwurf"}, {"level": 2, "text": "Rechne zuerst das Quadrat, dann die Produkte, dann die Summe.", "status": "entwurf"}, {"level": 3, "text": "Schreib es auf: f(−3) = −2 · (−3)² + (−4) · (−3).", "status": "entwurf"}]}, {"suffix": "home-s3-24e0a01233", "input_type": "NUMERIC", "frage": "Berechne f(−1) für f(x) = 2x² − 5x + 6.", "payload": {"kind": "short_input", "prompt": "Berechne f(−1) für f(x) = 2x² − 5x + 6."}, "params": {"a": 2, "b": -5, "c": 6, "x": -1}, "stufe": 3, "rolle": "home", "pm": {"1": {"ok": true}, "2": {"ok": true}, "3": {"ok": true}, "4": {"ok": true}, "5": {"ok": true}, "6": {"ok": true}, "7": {"ok": true}}, "afb": "II", "correct": ["13", "+13"], "acceptance": {"canonical": "13", "equivalents": ["+13"], "known_errors": {"7": "qf_quadrat_als_verdopplung", "9": "qf_einsetzen_vorzeichen", "15": "qf_ax_quadriert"}}, "parts": null, "figur": null, "optionen": null, "solution": "f(−1) = 2 · (−1)² + (−5) · (−1) + 6\n= 2 + 5 + 6\n= 13", "hints": [{"level": 1, "text": "Ersetze jedes x durch (−1).", "status": "entwurf"}, {"level": 2, "text": "Rechne zuerst das Quadrat, dann die Produkte, dann die Summe.", "status": "entwurf"}, {"level": 3, "text": "Schreib es auf: f(−1) = 2 · (−1)² + (−5) · (−1) + 6.", "status": "entwurf"}]}]'::jsonb)
             as v(suffix text, input_type text, frage text, payload jsonb, params jsonb, stufe int, rolle text,
                  pm jsonb, afb text, correct jsonb, acceptance jsonb, parts jsonb, figur jsonb, optionen jsonb,
                  solution text, hints jsonb)),
     neu as (
  insert into public.tasks (content_type, input_type, status, is_active, title, question, question_payload, parts, skill_key,
                            difficulty, afb, class_level, est_duration_sec, source, source_ref, einsatz, bauform_id,
                            bauform_version, params, stufe, rolle, kernidee_key, pruefmaschine)
  select 'exercise', v.input_type, 'draft', true, 'EIN-1' || ' · ' || v.rolle || ' · S' || v.stufe, v.frage,
         v.payload, coalesce(v.parts, '[]'::jsonb), 'term_einsetzen', v.stufe, v.afb, 9, 60, 'bauform',
         'EIN-1' || '-v' || b.version || '-' || v.suffix, '{session}', b.id, b.version, v.params, v.stufe,
         v.rolle, null, v.pm
    from b, v
  on conflict (source, source_ref) do nothing
  returning id, source_ref),
     loes as (
  insert into public.task_solutions (task_id, correct_answers, acceptance, solution, hints)
  select neu.id, v.correct, v.acceptance, v.solution, v.hints
    from neu join b on true join v on neu.source_ref = 'EIN-1' || '-v' || b.version || '-' || v.suffix
  returning task_id),
     fig as (
  -- Eine Figur je Aufgabe (task_figures) bzw. je Option einer Graph-Auswahl (task_figur_optionen); hochgeladen
  -- werden sie von scripts/figures/upload_figures.py (Rasit).
  insert into public.task_figures (task_id, generator, params, alt_text)
  select neu.id, v.figur ->> 'generator', v.figur -> 'params', v.figur ->> 'alt'
    from neu join b on true join v on neu.source_ref = 'EIN-1' || '-v' || b.version || '-' || v.suffix
   where v.figur is not null
  returning task_id)
insert into public.task_figur_optionen (task_id, option_id, generator, params, alt_text)
select neu.id, o ->> 'option', o ->> 'generator', o -> 'params', o ->> 'alt'
  from neu join b on true join v on neu.source_ref = 'EIN-1' || '-v' || b.version || '-' || v.suffix,
       jsonb_array_elements(coalesce(v.optionen, '[]')) o;
do $$ begin perform set_config('edvance.hinweis_status', '', true); perform set_config('edvance.bauform_export', '', true); end $$;
